<?php
if (!defined('JTMES_ROOT')) { define('JTMES_ROOT', realpath(dirname(__DIR__, 3)) ?: dirname(__DIR__, 3)); }
session_start();
require_once JTMES_ROOT . '/config/dp_config.php';
$EMBED = !empty($_GET['embed']);
if (!$EMBED) { require_once JTMES_ROOT . '/inc/sidebar.php'; require_once JTMES_ROOT . '/inc/dp_userbar.php'; }
require_once JTMES_ROOT . '/lib/auth_guard.php';
dp_auth_guard();
if (!function_exists('h')) { function h(?string $s): string { return htmlspecialchars($s ?? '', ENT_QUOTES, 'UTF-8'); } }
if (!function_exists('fmt_spec_4')) { function fmt_spec_4($v): string { if ($v === null || $v === '') return ''; if (!is_numeric((string)$v)) return (string)$v; return number_format((float)$v, 4, '.', ''); } }
function table_columns(PDO $pdo, string $table): array { $cols=[]; $stmt=$pdo->query("SHOW COLUMNS FROM `$table`"); foreach($stmt->fetchAll(PDO::FETCH_ASSOC) as $r){$cols[strtolower($r['Field'])]=true;} return $cols; }
try { $pdo = dp_get_pdo(); } catch (PDOException $e) { die('DB 접속 실패: ' . h($e->getMessage())); }
$headerCols = table_columns($pdo, 'oqc_header');
if (!function_exists('dp_session_user_no_local')) { function dp_session_user_no_local(): ?int { foreach(['ship_user_no','user_no','dp_user_no','account_no','no','No'] as $k){ if(isset($_SESSION[$k]) && is_numeric($_SESSION[$k])) return (int)$_SESSION[$k]; } return null; } }
if (!function_exists('dp_session_user_id_local')) { function dp_session_user_id_local(): ?string { foreach(['ship_user_id','user_id','userid','username','id','ID'] as $k){ if(!empty($_SESSION[$k])) return (string)$_SESSION[$k]; } return null; } }
if (!function_exists('dp_current_account_row_local')) { function dp_current_account_row_local(PDO $pdo): ?array { $no=dp_session_user_no_local(); if($no!==null){$st=$pdo->prepare('SELECT `No`,`ID`,`NAME`,`lv`,`role`,`status` FROM `account` WHERE `No`=:no LIMIT 1');$st->execute([':no'=>$no]);$r=$st->fetch(PDO::FETCH_ASSOC);if($r)return $r;} $id=dp_session_user_id_local(); if($id!==null&&$id!==''){$st=$pdo->prepare('SELECT `No`,`ID`,`NAME`,`lv`,`role`,`status` FROM `account` WHERE `ID`=:id LIMIT 1');$st->execute([':id'=>$id]);$r=$st->fetch(PDO::FETCH_ASSOC);if($r)return $r;} return null; } }
$viewerAccount = dp_current_account_row_local($pdo); $viewerLv=(int)($viewerAccount['lv']??0); $canManualMeasEdit=($viewerLv>=98);
if ($_SERVER['REQUEST_METHOD']==='POST' && (($_POST['action']??'')==='oqc_manual_meas_save')) {
  header('Content-Type: application/json; charset=utf-8');
  if(!$canManualMeasEdit){http_response_code(403); echo json_encode(['ok'=>false,'message'=>'권한이 없습니다.']); exit;}
  $headerId=(int)($_POST['header_id']??0); $postCustomer=$_POST['customer']??'LG'; if($postCustomer!=='LG'&&$postCustomer!=='JH')$postCustomer='LG';
  $postKey1=($postCustomer==='JH')?'jmeas_date':'meas_date'; $postKey2=($postCustomer==='JH')?'jmeas_date2':'meas_date2';
  if($headerId<=0){http_response_code(400); echo json_encode(['ok'=>false,'message'=>'header_id가 올바르지 않습니다.']); exit;}
  if(!isset($headerCols[$postKey1])){http_response_code(400); echo json_encode(['ok'=>false,'message'=>'측정일 컬럼이 없습니다.']); exit;}
  $date1=trim((string)($_POST['date1']??'')); $date2=trim((string)($_POST['date2']??''));
  foreach(['date1'=>$date1,'date2'=>$date2] as $label=>$val){ if($val!=='' && !preg_match('/^\d{4}-\d{2}-\d{2}$/',$val)){http_response_code(400); echo json_encode(['ok'=>false,'message'=>$label.' 형식이 올바르지 않습니다.']); exit;} }
  $check=$pdo->prepare('SELECT `id` FROM `oqc_header` WHERE `id`=:id LIMIT 1'); $check->execute([':id'=>$headerId]); if(!$check->fetch(PDO::FETCH_ASSOC)){http_response_code(404); echo json_encode(['ok'=>false,'message'=>'대상 헤더를 찾을 수 없습니다.']); exit;}
  if(isset($headerCols[$postKey2])) $sql="UPDATE `oqc_header` SET `{$postKey1}`=:d1, `{$postKey2}`=:d2 WHERE `id`=:id LIMIT 1"; else $sql="UPDATE `oqc_header` SET `{$postKey1}`=:d1 WHERE `id`=:id LIMIT 1";
  $st=$pdo->prepare($sql); $st->bindValue(':d1',($date1===''?null:$date1),($date1===''?PDO::PARAM_NULL:PDO::PARAM_STR)); if(isset($headerCols[$postKey2]))$st->bindValue(':d2',($date2===''?null:$date2),($date2===''?PDO::PARAM_NULL:PDO::PARAM_STR)); $st->bindValue(':id',$headerId,PDO::PARAM_INT); $st->execute();
  $recommend = $date1==='' ? $postKey1 : ((isset($headerCols[$postKey2])&&$date2==='') ? $postKey2 : '직접 수정');
  echo json_encode(['ok'=>true,'message'=>'저장되었습니다.','header_id'=>$headerId,'date1'=>$date1,'date2'=>$date2,'key1'=>$postKey1,'key2'=>isset($headerCols[$postKey2])?$postKey2:'','recommend'=>$recommend], JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); exit;
}
$part_name=$_GET['part_name']??''; $ship_date=$_GET['ship_date']??''; if($ship_date!==''&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',$ship_date))$ship_date=''; $kind=$_GET['kind']??'ALL';
$customer=$_GET['customer']??'LG'; if($customer!=='LG'&&$customer!=='JH')$customer='LG'; $customerLabel=($customer==='JH')?'자화전자(주)':'엘지이노텍(주)'; $measKey1=($customer==='JH')?'jmeas_date':'meas_date'; $measKey2=($customer==='JH')?'jmeas_date2':'meas_date2';
$stmt=$pdo->query("SELECT DISTINCT part_name FROM oqc_header ORDER BY part_name"); $part_list=$stmt->fetchAll(PDO::FETCH_COLUMN);
$headers=[]; $rows=[]; $ngMap=[]; $specMap=[];
if($part_name!==''&&$ship_date!==''){
  $params=[':part_name'=>$part_name,':ship_date'=>$ship_date]; $kind_sql=''; if($kind==='FAI'||$kind==='SPC'){$kind_sql=' AND h.kind = :kind';$params[':kind']=$kind;}
  $dateWhere=isset($headerCols['ship_date'])?" (h.ship_date = :ship_date OR (h.ship_date IS NULL AND h.lot_date = :ship_date)) ":" h.lot_date = :ship_date ";
  $selMeas=isset($headerCols[$measKey1])?", h.`{$measKey1}`":""; $selMeas2=isset($headerCols[$measKey2])?", h.`{$measKey2}`":"";
  $sql="SELECT h.id, h.part_name {$selMeas}{$selMeas2}, ".(isset($headerCols['ship_date'])?'h.ship_date,':'')." h.lot_date, h.tool_cavity, h.kind, h.source_file, h.excel_col FROM oqc_header h WHERE h.part_name=:part_name AND {$dateWhere} {$kind_sql} ORDER BY h.excel_col";
  $stmt=$pdo->prepare($sql); $stmt->execute($params); $headers=$stmt->fetchAll(PDO::FETCH_ASSOC);
  if($headers){
    $base=(int)$headers[0]['id']; $stmt=$pdo->prepare('SELECT row_index, point_no, spc_code FROM oqc_measurements WHERE header_id=:hid ORDER BY row_index'); $stmt->execute([':hid'=>$base]);
    foreach($stmt->fetchAll(PDO::FETCH_ASSOC) as $rd){$ri=(int)$rd['row_index'];$rows[$ri]=['point_no'=>$rd['point_no'],'spc_code'=>$rd['spc_code'],'values'=>[]];}
    $ids=array_column($headers,'id'); $in=implode(',',array_fill(0,count($ids),'?'));
    $stmt=$pdo->prepare("SELECT header_id,row_index,value FROM oqc_measurements WHERE header_id IN ($in) ORDER BY row_index, header_id"); $stmt->execute($ids); foreach($stmt->fetchAll(PDO::FETCH_ASSOC) as $d){$ri=(int)$d['row_index'];if(isset($rows[$ri]))$rows[$ri]['values'][(int)$d['header_id']]=$d['value'];}
    try{$stmt=$pdo->prepare("SELECT point_no, MAX(usl) AS usl, MAX(lsl) AS lsl FROM oqc_result_header WHERE header_id IN ($in) GROUP BY point_no");$stmt->execute($ids);foreach($stmt->fetchAll(PDO::FETCH_ASSOC) as $r){$specMap[$r['point_no']]=['usl'=>$r['usl'],'lsl'=>$r['lsl']];}$stmt=$pdo->prepare("SELECT header_id, point_no FROM oqc_result_header WHERE header_id IN ($in) AND result_ok=0");$stmt->execute($ids);foreach($stmt->fetchAll(PDO::FETCH_ASSOC) as $r){$ngMap[(int)$r['header_id']][$r['point_no']]=true;}}catch(Throwable $e){}
  }
}
?>
