-align:center;padding:8px 10px;border-bottom:1px solid rgba(255,255,255,.10);white-space:nowrap}tbody td{padding:8px 10px;font-size:11.5px;color:var(--fg);border-bottom:1px solid rgba(255,255,255,.06);white-space:nowrap;text-align:center}tbody tr td{background:var(--card)}tbody tr:nth-child(even) td{background:#26282c}tbody tr:hover td{background:rgba(29,185,84,.08)}th.col-head div.sub{font-size:10px;color:#57d68d}th.num,td.num{width:var(--sticky1);min-width:var(--sticky1);max-width:var(--sticky1)}th.spc,td.spc{width:var(--sticky2);min-width:var(--sticky2);max-width:var(--sticky2)}th.spec,td.spec{width:var(--sticky3);min-width:var(--sticky3);max-width:var(--sticky3)}th.spec2,td.spec2{width:var(--sticky4);min-width:var(--sticky4);max-width:var(--sticky4)}th.sticky,td.sticky{position:sticky;left:0;text-align:center}th.sticky2,td.sticky2{position:sticky;left:var(--sticky1);text-align:center;box-shadow:2px 0 0 rgba(255,255,255,.10)}th.sticky3,td.sticky3{position:sticky;left:calc(var(--sticky1) + var(--sticky2));text-align:center;box-shadow:2px 0 0 rgba(255,255,255,.10)}th.sticky4,td.sticky4{position:sticky;left:calc(var(--sticky1) + var(--sticky2) + var(--sticky3));text-align:center;box-shadow:2px 0 0 rgba(255,255,255,.10)}th.sticky,td.sticky,th.sticky2,td.sticky2,th.sticky3,td.sticky3,th.sticky4,td.sticky4{background:#202124;z-index:5}thead th.sticky,thead th.sticky2,thead th.sticky3,thead th.sticky4{background:#303134}tbody td.sticky,tbody td.sticky2,tbody td.sticky3,tbody td.sticky4{z-index:3;background:#202124}td.ng{background:rgba(232,93,93,.12)!important;color:#ffd1d1;font-weight:700}.manual-date-trigger.can-edit{cursor:pointer}.manual-date-trigger.can-edit:hover{color:#98ffbd;text-decoration:underline}.manual-meas-backdrop,.oqc-status-backdrop{position:fixed;inset:0;background:rgba(0,0,0,.72);z-index:10040;display:none;align-items:center;justify-content:center;padding:18px}.manual-meas-backdrop.open,.oqc-status-backdrop.open{display:flex}.manual-meas-modal{width:min(520px,calc(100vw - 24px));background:#23262b;border:1px solid rgba(255,255,255,.12);border-radius:18px;box-shadow:0 18px 40px rgba(0,0,0,.48);overflow:hidden}.manual-meas-head{padding:14px 18px;border-bottom:1px solid rgba(255,255,255,.08);font-size:20px;font-weight:800}.manual-meas-body{padding:18px}.manual-meas-meta{font-size:13px;line-height:1.7;margin-bottom:14px}.manual-meas-current{padding:12px 14px;border-radius:14px;background:#1e2126;border:1px solid rgba(255,255,255,.08)}.manual-meas-row{display:flex;align-items:center;gap:10px;margin-top:8px}.manual-meas-key{width:96px;min-width:96px;color:#b7c0cb}.manual-meas-row input{flex:1;height:36px;border-radius:10px;border:1px solid var(--border);background:#121417;color:var(--fg);padding:0 10px}.manual-meas-row button,.manual-meas-foot button{height:36px;padding:0 11px;border-radius:10px;border:1px solid rgba(255,255,255,.12);background:#343942;color:#fff;cursor:pointer}.manual-meas-hint{margin-top:12px;color:#8de6b0;font-weight:700}.manual-meas-error{display:none;margin-top:12px;color:#ffb4b4}.manual-meas-error.show{display:block}.manual-meas-foot{display:flex;justify-content:flex-end;gap:10px;padding:14px 18px;border-top:1px solid rgba(255,255,255,.08)}.manual-meas-foot button.primary{background:rgba(29,185,84,.22);border-color:rgba(29,185,84,.55)}.oqc-status-backdrop{z-index:10030}.oqc-status-shell{width:100%;height:100%;display:flex;flex-direction:column;background:#202124;border:1px solid rgba(255,255,255,.14);border-radius:18px;box-shadow:0 22px 54px rgba(0,0,0,.58);overflow:hidden}.oqc-status-head{height:52px;display:flex;align-items:center;justify-content:space-between;padding:0 16px;background:#25282e;border-bottom:1px solid rgba(255,255,255,.10)}.oqc-status-title{font-size:18px;font-weight:850;color:#fff}.oqc-status-close{width:38px;height:36px;border-radius:11px;border:1px solid rgba(255,255,255,.16);background:#323741;color:#fff;font-size:22px;cursor:pointer}.oqc-status-frame{width:100%;height:100%;border:0;background:#202124}.float-head{display:none}
