<?php if($headers): ?><div class="summary"><span>납품처: <strong><?=h($customerLabel)?></strong></span><span>모델: <strong><?=h($headers[0]['part_name'])?></strong></span><span>출하 기준 날짜: <strong><?=h($ship_date)?></strong></span><span>NG: <strong style="color:#ffb4b4;">빨간색</strong></span><span class="file">파일: <?=h($headers[0]['source_file'])?></span></div><div id="floatHead" class="float-head" aria-hidden="true"><div class="float-scroller"></div></div><div class="table-wrap"><table><thead><tr><th class="sticky num">FAI</th><th class="sticky2 spc">SPC</th><th class="sticky3 spec">USL</th><th class="sticky4 spec2">LSL</th><?php foreach($headers as $hrow): ?><th class="col-head"><div class="top"><?php $top2=$hrow[$measKey2]??null;$top1=$hrow[$measKey1]??null;if($top2&&$top1)echo h($top2).'<br>'.h($top1);elseif($top1)echo h($top1);elseif($top2)echo h($top2);else echo '&nbsp;'; ?></div><div class="main"><?=h($hrow['tool_cavity'])?></div><?php $curDate1=(string)($hrow[$measKey1]??'');$curDate2=(string)($hrow[$measKey2]??''); ?><div class="sub manual-date-trigger <?=$canManualMeasEdit?'can-edit':'readonly'?>" data-header-id="<?=(int)$hrow['id']?>" data-customer="<?=h($customer)?>" data-customer-label="<?=h($customerLabel)?>" data-part-name="<?=h($headers[0]['part_name'])?>" data-tool-cavity="<?=h($hrow['tool_cavity'])?>" data-excel-col="<?=h($hrow['excel_col'])?>" data-kind="<?=h($hrow['kind'])?>" data-date1="<?=h($curDate1)?>" data-date2="<?=h($curDate2)?>" data-key1="<?=h($measKey1)?>" data-key2="<?=h($measKey2)?>" title="<?=$canManualMeasEdit?'더블클릭하여 측정일 수동 입력/수정/삭제':''?>"><?=h($hrow['excel_col'])?> (<?=h($hrow['kind'])?>)</div></th><?php endforeach; ?></tr></thead><tbody><?php foreach($rows as $row): ?><?php $pno=$row['point_no'];$spec=$specMap[$pno]??null;$usl=($spec&&$spec['usl']!==null&&$spec['usl']!=='')?fmt_spec_4($spec['usl']):'';$lsl=($spec&&$spec['lsl']!==null&&$spec['lsl']!=='')?fmt_spec_4($spec['lsl']):''; ?><tr><td class="sticky num"><?=h($row['point_no'])?></td><td class="sticky2 spc"><?=h($row['spc_code'])?></td><td class="sticky3 spec"><?=$usl===''?'':h($usl)?></td><td class="sticky4 spec2"><?=$lsl===''?'':h($lsl)?></td><?php foreach($headers as $hrow): ?><?php $hid=(int)$hrow['id'];$val=$row['values'][$hid]??'';$dispVal=($val===''||$val===null)?'':fmt_spec_4($val);$isNg=(strpos((string)$pno,'(DC)')===false)&&isset($ngMap[$hid][$pno]); ?><td class="<?=$isNg?'ng':''?>"><?=$dispVal===''?'':h($dispVal)?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
