<script>(function(){const openBtn=document.getElementById('openOqcStatusModal'),backdrop=document.getElementById('oqcStatusBackdrop'),closeBtn=document.getElementById('closeOqcStatusModal'),frame=document.getElementById('oqcStatusFrame');if(!openBtn||!backdrop||!closeBtn||!frame)return;function selectedCustomer(){const sel=document.querySelector('select[name="customer"]');return sel&&sel.value==='JH'?'JH':'LG'}function selectedModel(){const sel=document.querySelector('select[name="part_name"]');const val=sel?(sel.value||sel.options[sel.selectedIndex]?.text||''):'';const up=val.toUpperCase().replace(/[\s_-]/g,'');if(up.indexOf('IRBASE')>=0)return'MEM-IR-BASE';if(up.indexOf('XCARRIER')>=0)return'MEM-X-CARRIER';if(up.indexOf('YCARRIER')>=0)return'MEM-Y-CARRIER';if(up.indexOf('ZCARRIER')>=0)return'MEM-Z-CARRIER';if(up.indexOf('ZSTOPPER')>=0)return'MEM-Z-STOPPER';return'MEM-IR-BASE'}function openModal(){const qs=new URLSearchParams();qs.set('embed','1');qs.set('customer',selectedCustomer());qs.set('model',selectedModel());frame.src='oqc_status_modal.php?'+qs.toString();backdrop.classList.add('open');backdrop.setAttribute('aria-hidden','false');document.documentElement.style.overflow='hidden';document.body.style.overflow='hidden'}function closeModal(){backdrop.classList.remove('open');backdrop.setAttribute('aria-hidden','true');document.documentElement.style.overflow='';document.body.style.overflow=''}openBtn.addEventListener('click',openModal);closeBtn.addEventListener('click',closeModal);backdrop.addEventListener('click',e=>{if(e.target===backdrop)closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&backdrop.classList.contains('open'))closeModal()})})();</script>
<?php if($headers&&$canManualMeasEdit): ?><script>(function(){const backdrop=document.getElementById('manualMeasBackdrop'),form=document.getElementById('manualMeasForm');if(!backdrop||!form)return;const q=id=>document.getElementById(id),headerIdEl=q('manualMeasHeaderId'),customerEl=q('manualMeasCustomer'),customerLabelEl=q('manualMeasCustomerLabel'),partNameEl=q('manualMeasPartName'),toolCavityEl=q('manualMeasToolCavity'),excelColEl=q('manualMeasExcelCol'),key1El=q('manualMeasKey1'),key2El=q('manualMeasKey2'),date1El=q('manualMeasDate1'),date2El=q('manualMeasDate2'),hintEl=q('manualMeasHint'),errorEl=q('manualMeasError'),cancelBtn=q('manualMeasCancel'),saveBtn=q('manualMeasSave');let activeTrigger=null;function showError(msg){errorEl.textContent=msg||'';errorEl.classList.toggle('show',!!msg)}function updateHint(){const k1=key1El.textContent.trim(),k2=key2El.textContent.trim(),v1=date1El.value.trim(),v2=date2El.value.trim();hintEl.textContent=!v1?'저장 대상 추천: '+k1:(k2&&!v2?'저장 대상 추천: '+k2:'저장 대상 추천: 직접 수정')}function openManual(t){activeTrigger=t;const ds=t.dataset;headerIdEl.value=ds.headerId||'';customerEl.value=ds.customer||'LG';customerLabelEl.textContent=ds.customerLabel||'';partNameEl.textContent=ds.partName||'';toolCavityEl.textContent=ds.toolCavity||'';excelColEl.textContent=((ds.excelCol||'')+' ('+(ds.kind||'')+')').trim();key1El.textContent=ds.key1||'meas_date';key2El.textContent=ds.key2||'meas_date2';date1El.value=ds.date1||'';date2El.value=ds.date2||'';showError('');updateHint();backdrop.classList.add('open');backdrop.setAttribute('aria-hidden','false')}document.querySelectorAll('.manual-date-trigger.can-edit').forEach(t=>t.addEventListener('dblclick',()=>openManual(t)));cancelBtn.addEventListener('click',()=>backdrop.classList.remove('open'));backdrop.addEventListener('click',e=>{if(e.target===backdrop)backdrop.classList.remove('open')});form.querySelectorAll('button[data-clear]').forEach(btn=>btn.addEventListener('click',()=>{if(btn.dataset.clear==='1')date1El.value='';if(btn.dataset.clear==='2')date2El.value='';updateHint()}));date1El.addEventListener('change',updateHint);date2El.addEventListener('change',updateHint);form.addEventListener('submit',e=>{e.preventDefault();showError('');saveBtn.disabled=true;fetch(location.pathname+location.search,{method:'POST',body:new FormData(form),credentials:'same-origin'}).then(r=>r.json().then(j=>{if(!r.ok||!j.ok)throw new Error(j.message||'저장 실패');return j})).then(()=>location.reload()).catch(err=>showError(err.message||'저장 실패')).finally(()=>saveBtn.disabled=false)});})();</script><?php endif; ?>
